function text_cl(text){
    arr = text.replace('','').split('\n');

    res = [];
    for (i in arr){
        if (arr[i] != ''); 
            res.push(arr[i].replace('\r',''))
    }
    // console.log(res.join(','))
    return res.join(',');





};



var  text = Forguncy.Page.getCell("text").getValue();

var res = text_cl(text);

Forguncy.Page.getCell('res').setValue(res);
